# Shared helpers for adapters/*/deploy.sh. Source this after setting QUIET, REPO_DIR,
# ACTUAL_HOME, BACKUP_DIR and (for Codex legacy-entry migration) CODEX_MODE.
#
# Ownership model: every file/link a deploy writes either carries a "generated by
# ai-main" marker or is an exact-recognition migration of a known legacy ai-main entry.
# Anything unrecognized is preserved and fails the deploy instead of being overwritten.

RED='\033[0;31m'; GREEN='\033[0;32m'; BLUE='\033[0;34m'; CYAN='\033[0;36m'; YELLOW='\033[0;33m'; BOLD='\033[1m'; NC='\033[0m'

OMP_MARKER="<!-- generated by ai-main — OMP-first entry -->"
# The marker text is a recognition key for already-deployed entries: keep it byte-identical
# even though the Codex body now comes from build/full.
CODEX_MARKER="<!-- generated by ai-main — Codex entry (scripts/deploy-omp.sh --codex; source: build/lean/SYSTEM.md) -->"

log()  { [ "$QUIET" -eq 1 ] && return 0; echo -e "$@"; }
fail() { echo -e "${RED}✗ $*${NC}" >&2; exit 1; }

backup_file() {
    mkdir -p "$BACKUP_DIR"
    local dest="${BACKUP_DIR}/$(basename "$1").$(date +%H%M%S)"
    cp -p "$1" "$dest" && log "  ${YELLOW} backup: $1 -> $dest${NC}"
}

expand_placeholders() {
    # stdin -> stdout
    sed -e "s|{{HOME}}|${ACTUAL_HOME}|g" -e "s|{{AI_MAIN}}|${REPO_DIR}|g"
}

# --------------------------------------------------------------------------
# Entry deployment: marker-aware overwrite, exact-recognition migration,
# preserve anything else.
#   deploy_entry <generated-file> <target> <label>
# --------------------------------------------------------------------------
deploy_entry() {
    local generated="$1" target="$2" label="$3"

    [ ! -L "$target" ] || fail "$label: $target is a user-owned symlink — preserved"

    if [ ! -e "$target" ]; then
        mv "$generated" "$target"
        log "  ${GREEN}✓ installed $label: $target${NC}"
        return 0
    fi

    local first_line
    IFS= read -r first_line < "$target" || true
    if [ "$first_line" = "$OMP_MARKER" ] || [ "$first_line" = "$CODEX_MARKER" ]; then
        if cmp -s "$generated" "$target"; then
            log "  ${GREEN}✓ $label already current: $target${NC}"
            rm -f "$generated"
        else
            mv "$generated" "$target"
            log "  ${GREEN}✓ refreshed managed $label: $target${NC}"
        fi
        return 0
    fi

    # Approved migration: the exact legacy ai-main OMP entry (5 build/full imports).
    if is_legacy_omp_entry "$target"; then
        backup_file "$target"
        mv "$generated" "$target"
        log "  ${GREEN}✓ migrated legacy OMP entry (exact recognition): $target${NC}"
        return 0
    fi

    # Approved migration: the exact legacy compiled Codex entry (AGENTS.md.template).
    if [ "$CODEX_MODE" -eq 1 ] && is_legacy_compiled_codex_entry "$target"; then
        backup_file "$target"
        mv "$generated" "$target"
        log "  ${GREEN}✓ migrated legacy compiled Codex entry (exact recognition): $target${NC}"
        return 0
    fi

    fail "$label: $target is not ai-main-managed and not a recognized legacy entry — preserved; e.g. mv '$target' '${target}.user' then re-run"
}

# Structural exact recognition of the pre-OMP entry ai-main wrote by hand:
#   # Shared AI guidance
#   <blank>
#   @<prefix>/build/full/profile.md
#   @<prefix>/build/full/style.md
#   @<prefix>/build/full/workflow.md
#   @<prefix>/build/full/SHARED.md
#   @<prefix>/build/full/RULES.md
is_legacy_omp_entry() {
    local f="$1" prefix expected content
    [ -f "$f" ] || return 1
    content="$(cat "$f")"    # command substitution strips trailing newlines
    prefix="$(printf '%s\n' "$content" | sed -n 's|^@\(.*/build/full/\)profile\.md$|\1|p')"
    [ "$prefix" = "${REPO_DIR}/build/full/" ] || return 1
    expected="# Shared AI guidance

@${prefix}profile.md
@${prefix}style.md
@${prefix}workflow.md
@${prefix}SHARED.md
@${prefix}RULES.md"
    [ "$content" = "$expected" ]
}

# Rebuild exactly what install.sh compile_template produced for the legacy
# Codex entry (adapters/codex/AGENTS.md.template with inlined imports) and compare.
is_legacy_compiled_codex_entry() {
    local target="$1" expected
    [ -f "${REPO_DIR}/adapters/codex/AGENTS.md.template" ] || return 1
    expected="$(mktemp)"
    local line import_path base_name
    : > "$expected"
    while IFS= read -r line || [ -n "$line" ]; do
        if [[ "$line" =~ ^@ ]]; then
            import_path="${line#@}"
            import_path="${import_path//\{\{HOME\}\}/$ACTUAL_HOME}"
            import_path="${import_path//\{\{AI_MAIN\}\}/$REPO_DIR}"
            base_name="$(basename "$import_path")"
            if [ -f "$import_path" ]; then
                cat "$import_path" >> "$expected"; echo "" >> "$expected"
            elif [ -f "${REPO_DIR}/config/${base_name}" ]; then
                cat "${REPO_DIR}/config/${base_name}" >> "$expected"; echo "" >> "$expected"
            elif [ -f "${REPO_DIR}/memory/${base_name}" ]; then
                cat "${REPO_DIR}/memory/${base_name}" >> "$expected"; echo "" >> "$expected"
            else
                echo "# Broken Import: $line" >> "$expected"
            fi
        else
            printf '%s\n' "$line" | expand_placeholders >> "$expected"
        fi
    done < "${REPO_DIR}/adapters/codex/AGENTS.md.template"
    if cmp -s "$target" "$expected"; then
        rm -f "$expected"; return 0
    fi
    rm -f "$expected"; return 1
}
